<?php declare(strict_types=1);require dirname(__DIR__).'/_bootstrap.php';require_post();$data=json_input();$identity=trim((string)($data['identity']??''));$password=(string)($data['password']??'');$deviceId=trim((string)($data['device_id']??''));if($identity===''||strlen($identity)>190||$password===''||$deviceId===''||strlen($deviceId)>190)json_response(false,'Credentials and a valid device ID are required',null,422);
$ip=client_ip();$identityHash=hash('sha256',strtolower($identity));$recent=db()->prepare('SELECT COUNT(*) FROM login_attempts WHERE (ip_address=? OR identity_hash=?) AND successful=0 AND attempted_at>DATE_SUB(NOW(),INTERVAL 15 MINUTE)');$recent->execute([$ip,$identityHash]);if((int)$recent->fetchColumn()>=5)json_response(false,'Too many login attempts. Try again later.',null,429);
$stmt=db()->prepare('SELECT * FROM users WHERE (email=? OR mobile=?) LIMIT 1');$stmt->execute([$identity,$identity]);$user=$stmt->fetch();$ok=$user&&$user['status']==='ACTIVE'&&password_verify($password,$user['password_hash']);db()->prepare('INSERT INTO login_attempts(identity_hash,ip_address,successful) VALUES(?,?,?)')->execute([$identityHash,$ip,$ok?1:0]);if(!$ok){log_security($user?(int)$user['id']:null,'LOGIN_FAILED','MEDIUM','Failed mobile API login');json_response(false,'Invalid credentials',null,401);}
$known=db()->prepare('SELECT status,ip_address FROM user_devices WHERE user_id=? AND device_id=?');$known->execute([$user['id'],$deviceId]);$device=$known->fetch();if($device&&$device['status']==='BLOCKED'){log_security((int)$user['id'],'BLOCKED_DEVICE_LOGIN','HIGH','Blocked device attempted login',['device_id'=>$deviceId]);json_response(false,'Device is blocked',null,403);}$isNew=!$device;$ipChanged=$device&&!empty($device['ip_address'])&&!hash_equals((string)$device['ip_address'],$ip);db()->prepare('INSERT INTO user_devices(user_id,device_id,device_name,platform,ip_address,status,last_active_at) VALUES(?,?,?, ?,?,"ACTIVE",NOW()) ON DUPLICATE KEY UPDATE ip_address=VALUES(ip_address),last_active_at=NOW()')->execute([$user['id'],$deviceId,substr((string)($data['device_name']??'Unknown device'),0,120),substr((string)($data['platform']??'Unknown'),0,30),$ip]);
$token=bin2hex(random_bytes(32));$hash=hash('sha256',$token);db()->prepare('INSERT INTO user_sessions(user_id,token_hash,device_id,ip_address,user_agent,expires_at) VALUES(?,?,?,?,?,DATE_ADD(NOW(),INTERVAL 30 DAY))')->execute([$user['id'],$hash,$deviceId,$ip,user_agent()]);db()->prepare('UPDATE users SET last_login_at=NOW(),last_login_ip=? WHERE id=?')->execute([$ip,$user['id']]);if($isNew){$deviceCount=db()->prepare('SELECT COUNT(*) FROM user_devices WHERE user_id=?');$deviceCount->execute([$user['id']]);$risk=(int)$deviceCount->fetchColumn()>2?'HIGH':'MEDIUM';log_security((int)$user['id'],'NEW_DEVICE_LOGIN',$risk,'New device registered during login',['device_id'=>$deviceId]);}if($ipChanged)log_security((int)$user['id'],'IP_CHANGED','MEDIUM','Known device logged in from a new IP',['device_id'=>$deviceId]);log_security((int)$user['id'],'LOGIN_SUCCESS','LOW','Mobile API login successful',['device_id'=>$deviceId]);json_response(true,'Login successful',['token'=>$token,'expires_in'=>2592000]);
